{"content": "    51|  <span style="font-size:0.75rem;color:var(--muted);margin-left:auto" id="uptime"></span>
    52|</div>
    53|
    54|<div class="main">
    55|  <!-- 统计卡片 -->
    56|  <div class="grid">
    57|    <div class="card"><h3>📊 总请求数</h3><div class="std-v blue" id="tReq">0</div></div>
    58|    <div class="card"><h3>🎯 Token 消耗</h3><div class="std-v purple" id="tTok">0</div></div>
    59|    <div class="card"><h3>❌ 错误数</h3><div class="std-v pink" id="tErr">0</div></div>
    60|    <div class="card"><h3>🚀 运行时间</h3><div class="std-v" style="color:#4f0" id="uptimeCard">--</div></div>
    61|  </div>
    62|
    63|  <!-- 模型管理 + 测试聊天 -->
    64|  <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px">
    65|    <div class="card">
    66|      <h3>🔧 模型管理</h3>
    67|      <div id="models"></div>
    68|    </div>
    69|    <div class="card">
    70|      <h3>💬 测试聊天</h3>
    71|      <div class="chat-box" id="chatBox">👋 阿罗娜在这里！输入消息测试中转站～</div>
    72|      <div class="chat-input">
    73|        <input id="chatInput" placeholder="说点什么..." onkeydown="if(event.key==='Enter')sendChat()">
    74|        <button class="btn btn-pink" onclick="sendChat()">发送</button>
    75|      </div>
    76|      <select id="chatModel" style="margin-top:8px;background:rgba(0,0,0,0.3);border:1px solid rgba(126,200,227,0.15);border-radius:8px;padding:8px;color:var(--text);width:100%"></select>
    77|    </div>
    78|  </div>
    79|
    80|  <!-- 最近请求 -->
    81|  <div class="card">
    82|    <h3>📋 最近请求（实时）</h3>
    83|    <div class="table-wrapper"><table><thead><tr><th>时间</th><th>模型</th><th>状态</th><th>Token</th></tr></thead><tbody id="recent"></tbody></table></div>
    84|  </div>
    85|</div>
    86|
    87|<script>
    88|const BASE = '';
    89|let refreshTimer;
    90|
    91|async function load() {
    92|  try {
    93|    const r = await fetch('/dashboard/stats');
    94|    const d = await r.json();
    95|    
    96|    document.getElementById('tReq').textContent = d.total_requests;
    97|    document.getElementById('tTok').textContent = (d.total_tokens/1000).toFixed(1)+'K';
    98|    document.getElementById('tErr').textContent = d.errors;
    99|    document.getElementById('uptime').textContent = '⏱ '+d.config.host+':'+d.config.port;
   100|    
   101|    // Models
   102|    document.getElementById('models').innerHTML = d.config.models.map(m=>`
   103|      <div class="model-row">
   104|        <div><div class="model-name">${m.name}</div><div class="model-prov">${m.id}</div></div>
   105|        <button class="toggle ${m.enabled?'on':'off'}" onclick="toggleModel('${m.id}')">${m.enabled?'已启用':'已停用'}</button>
   106|      </div>
   107|    `).join('');
   108|    
   109|    // Chat model select
   110|    document.getElementById('chatModel').innerHTML = d.config.models.filter(m=>m.enabled).map(m=>`
   111|      <option value="${m.id}">${m.name} (${m.id})</option>
   112|    `).join('');
   113|    
   114|    // Recent requests (reverse)
   115|    if(d.recent_requests) {
   116|      document.getElementById('recent').innerHTML = d.recent_requests.slice().reverse().map(req=>`
   117|        <tr><td>${new Date(req.time).toLocaleTimeString()}</td><td>${req.model}</td><td class="${req.status===200?'ok':'err'}">${req.status}</td><td>${req.tokens}</td></tr>
   118|      `).join('');
   119|    }
   120|    
   121|    document.getElementById('dot').style.background = '#4f0';
   122|  } catch(e) {
   123|    document.getElementById('dot').style.background = '#f44';
   124|  }
   125|}
