  const input = document.getElementById('chatInput');
  const box = document.getElementById('chatBox');
  const sel = document.getElementById('chatModel');
  const ws = document.getElementById('wildcardSel');
  let model = sel.value;
  // 如果选了通配，用子菜单的模型ID
  if (model === 'qwen/*' && ws.value) {
    model = ws.value;
  }
  const btn = document.querySelector('.btn-pink');

  if(!input.value.trim()) return;
  if(model === 'qwen/*' && !ws.value) {
    box.textContent += '\n\n⚠️ 请先在下方选择百炼模型';
    return;
  }

  box.textContent += '\n\n🧑 你: '+input.value;
  box.scrollTop = box.scrollHeight;
  btn.disabled = true;

  try {
    const r = await fetch('/v1/chat/completions', {
      method:'POST',
      headers:{'Content-Type':'application/json','Authorization':'Bearer sk-local-apirelay-2026'},
      body:JSON.stringify({
        model:model,
        messages:[{role:'user',content:input.value}],
        max_tokens:500
      })
    });
    const data = await r.json();
    const reply = data.choices?.[0]?.message?.content || JSON.stringify(data);
    box.textContent += '\n\n🌸 阿罗娜: '+reply;
  } catch(e) {
    box.textContent += '\n\n❌ 错误: '+e.message;
  }

  box.scrollTop = box.scrollHeight;
  input.value = '';
  btn.disabled = false;
  load();
}

function onModelChange() {
  const sel = document.getElementById('chatModel');
  const ws = document.getElementById('wildcardSel');
  if (sel.value === 'qwen/*') {
    ws.style.display = 'block';
    if (ws.options.length <= 1) loadDashscopeModels();
  } else {
    ws.style.display = 'none';
  }
}

function onWildcardPick() {
  // just for UX, the actual model ID is read in sendChat
}

async function loadDashscopeModels() {
  const ws = document.getElementById('wildcardSel');
  try {
    const r = await fetch('/v1/models/dashscope', {
      headers: {'Authorization': 'Bearer sk-local-apirelay-2026'}
    });
